# Definition for a binary tree node.
class TreeNode:
    def __init__(self, x):
        self.val = x
        self.left = None
        self.right = None

def findClosestLeaf(root: TreeNode, k: int) -> int:
    # Step 1: Use DFS to build a graph: node value -> list of neighboring nodes
    from collections import defaultdict, deque

    graph = defaultdict(list)
    node_map = {}

    def dfs(node, parent):
        if not node:
            return
        node_map[node.val] = node
        if parent:
            graph[node.val].append(parent.val)
            graph[parent.val].append(node.val)
        if node.left:
            dfs(node.left, node)
        if node.right:
            dfs(node.right, node)
    dfs(root, None)

    # Step 2: BFS from node 'k', return the first leaf encountered
    queue = deque([k])
    visited = set()
    while queue:
        cur = queue.popleft()
        node = node_map[cur]
        # If this is a leaf, return its value
        if not node.left and not node.right:
            return cur
        visited.add(cur)
        for neighbor in graph[cur]:
            if neighbor not in visited:
                queue.append(neighbor)
